  function getSelectedGestorObj() {
    return GESTORES_BCN_INTEL.find(g => g.id === ReviewState.gestorFilter) || GESTORES_BCN_INTEL[0];
  }

  function getGestorRichData(gid) {
    const carteras = window.HO_CARTERAS_PAYLOAD || {};
    const gestoresList = Array.isArray(carteras.gestores) ? carteras.gestores : [];
    const allServices = HO_DATA.servicios || [];
    const counts = getGestorCounts(gid);

    if (!gid || gid === 'todos') {
      const totProy = gestoresList.reduce((acc, g) => acc + ((g.kpis && g.kpis.proyectos_activos) || 0), 0) || counts.total;
      const totHoras = gestoresList.reduce((acc, g) => acc + ((g.kpis && g.kpis.horas_contratadas_activas) || 0), 0);
      const totTrab = gestoresList.reduce((acc, g) => acc + ((g.kpis && g.kpis.trabajadores) || 0), 0);
      const totTrabHoy = gestoresList.reduce((acc, g) => acc + ((g.kpis && g.kpis.trabajando_hoy) || 0), 0);
      const totBaja = gestoresList.reduce((acc, g) => acc + ((g.kpis && g.kpis.en_baja) || 0), 0);
      const totVac = gestoresList.reduce((acc, g) => acc + ((g.kpis && g.kpis.de_vacaciones) || 0), 0);
      const totFin45 = gestoresList.reduce((acc, g) => acc + ((g.kpis && g.kpis.contratos_fin_45d) || 0), 0);
      const totApoyos = gestoresList.reduce((acc, g) => acc + ((g.kpis && g.kpis.apoyos_externos) || 0), 0);
      return {
        id: 'todos',
        nombre: 'CONSOLIDADO BARCELONA (9 GESTORES · DIVISIÓN 0801)',
        nombre_corto: 'Toda Barcelona',
        doc: '0801',
        rol: 'Dirección de Operaciones Barcelona · Consolidado 9 Gestores',
        servicios_consolidados: counts.total,
        cubiertos: counts.ok,
        descubiertos: counts.fallos,
        salud_pct: counts.total > 0 ? Math.round((counts.ok / counts.total) * 100) : 100,
        proyectos_activos_sap: totProy,
        horas_contratadas: Math.round(totHoras),
        trabajadores_plantilla: totTrab || 685,
        trabajando_hoy: totTrabHoy || 436,
        en_baja: totBaja || 105,
        de_vacaciones: totVac || 34,
        contratos_fin_45d: totFin45 || 62,
        apoyos_externos: totApoyos
      };
    }

    const gMeta = GESTORES_BCN_INTEL.find(g => g.id === gid) || GESTORES_BCN_INTEL[0];
    const gCartera = gestoresList.find(g => g.id === gid || g.id_responsable_proyecto === gMeta.doc) || {};
    const k = gCartera.kpis || {};
    return {
      id: gMeta.id,
      nombre: gCartera.nombre || gMeta.nombre,
      nombre_corto: gMeta.nombre_corto,
      doc: gMeta.doc,
      rol: gCartera.rol || 'Gestor de Operaciones Barcelona (0801)',
      servicios_consolidados: counts.total,
      cubiertos: counts.ok,
      descubiertos: counts.fallos,
      salud_pct: counts.total > 0 ? Math.round((counts.ok / counts.total) * 100) : 100,
      proyectos_activos_sap: k.proyectos_activos || counts.total,
      horas_contratadas: Math.round(k.horas_contratadas_activas || (counts.total * 1450)),
      trabajadores_plantilla: k.trabajadores || 0,
      trabajando_hoy: k.trabajando_hoy || 0,
      en_baja: k.en_baja || 0,
      de_vacaciones: k.de_vacaciones || 0,
      contratos_fin_45d: k.contratos_fin_45d || 0,
      apoyos_externos: k.apoyos_externos || 0
    };
  }

  function getGestorCounts(gid) {
    const all = HO_DATA.servicios || [];
    if (!gid || gid === 'todos') {
      const ok = all.filter(s => s.estado === 'OK').length;
      return { total: all.length, ok: ok, fallos: all.length - ok };
    }
    const gObj = GESTORES_BCN_INTEL.find(g => g.id === gid);
    const filtered = all.filter(s => {
      if (String(s.id_gestor || '').trim() === gid) return true;
      if (gObj && gObj.match_names && s.gestor) {
        const gUp = String(s.gestor).toUpperCase();
        return gObj.match_names.some(m => gUp.includes(m));
      }
      return false;
    });
    const ok = filtered.filter(s => s.estado === 'OK').length;
    return { total: filtered.length, ok: ok, fallos: filtered.length - ok };
  }

  function getActiveServicesList() {
    let list = HO_DATA.servicios || [];
    if (ReviewState.gestorFilter && ReviewState.gestorFilter !== 'todos') {
      const gObj = getSelectedGestorObj();
      if (gObj) {
        list = list.filter(s => {
          if (String(s.id_gestor || '').trim() === gObj.id) return true;
          if (gObj.match_names && s.gestor) {
            const gUp = String(s.gestor).toUpperCase();
            if (gObj.match_names.some(m => gUp.includes(m))) return true;
          }
          return false;
        });
      }
    }
    return list;
  }

  function getActiveEmployeesList() {
    let emps = [];
    if (window.HO_CARTERAS_PAYLOAD && Array.isArray(window.HO_CARTERAS_PAYLOAD.trabajadores) && window.HO_CARTERAS_PAYLOAD.trabajadores.length > 0) {
      emps = window.HO_CARTERAS_PAYLOAD.trabajadores;
    } else if (Array.isArray(HO_DATA.empleados)) {
      emps = HO_DATA.empleados;
    }
    if (ReviewState.gestorFilter && ReviewState.gestorFilter !== 'todos') {
      const gObj = getSelectedGestorObj();
      if (gObj) {
        emps = emps.filter(e => {
          const gId = String(e.gestor_id || e.id_gestor || e.gestor_proyecto_principal_id || '').trim();
          if (gId === gObj.id || gId === gObj.doc) return true;
          const gNom = String(e.responsable_corto || e.responsable_rrhh || e.gestor || '').toUpperCase();
          if (gObj.match_names && gObj.match_names.some(m => gNom.includes(m))) return true;
          return false;
        });
      }
    }
    return emps;
  }

  window.setHOIntelGestorFilter = function (gid) {
    ReviewState.gestorFilter = gid || 'todos';
    ReviewState.scannerIndex = 0;
    const gObj = getSelectedGestorObj();
    const counts = getGestorCounts(ReviewState.gestorFilter);
    ReviewState.auditLogs.unshift({
      time: new Date().toLocaleTimeString(),
      type: 'info',
      text: `🎯 Filtro en tiempo real activado: ${gObj.nombre_corto.toUpperCase()} (${counts.total} servicios consolidados · ${counts.ok} cubiertos · ${counts.fallos} descubiertos).`
    });
    if (ReviewState.auditLogs.length > 50) ReviewState.auditLogs.pop();

    if (typeof window.showToast === 'function') {
      window.showToast(`🧠 Filtrando en tiempo real por: ${gObj.nombre_corto} (${counts.total} servicios)`, 'bg-blue');
    }
    if (window.renderAppShell) {
      window.renderAppShell();
    }
  };

